type rankedStartedReader struct {
	io.Reader
	entered chan struct{}
	once    sync.Once
}

func (r *rankedStartedReader) Read(p []byte) (int, error) {
	r.once.Do(func() { close(r.entered) })
	return r.Reader.Read(p)
}

func TestRankedMCP_CancelStopsIdleRead(t *testing.T) {
	t.Parallel()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	r, w := io.Pipe()
	defer r.Close()
	defer w.Close()
	started := &rankedStartedReader{Reader: r, entered: make(chan struct{})}
	done := make(chan error, 1)
	root := NewRootCmd()
	go func() { done <- runMCPServer(ctx, root, started, io.Discard) }()
	select {
	case <-started.entered:
	case <-time.After(5 * time.Second):
		t.Fatal("server never started reading")
	}
	cancel()
	select {
	case <-done:
		return
	case <-time.After(300 * time.Millisecond):
		// Release the blocked read before reporting the failed contract.
		_ = w.Close()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Fatal("server remained blocked even after pipe close")
		}
		t.Fatal("context cancellation did not stop an idle MCP server; input had to be closed separately")
	}
}

func TestRankedBundle_FailurePreservesExistingOutput(t *testing.T) {
	t.Parallel()
	repo := t.TempDir()
	testutil.InitRepo(t, repo)
	if err := os.Symlink(t.TempDir(), filepath.Join(repo, ".entire")); err != nil {
		t.Fatal(err)
	}
	out := filepath.Join(t.TempDir(), "previous.zip")
	before := []byte("previous valuable archive")
	if err := os.WriteFile(out, before, 0o600); err != nil {
		t.Fatal(err)
	}
	err := writeDoctorBundle(context.Background(), repo, out, true)
	if err == nil {
		t.Fatal("expected refusal of symlinked .entire")
	}
	after, readErr := os.ReadFile(out)
	if readErr != nil {
		t.Fatal(readErr)
	}
	if !bytes.Equal(before, after) {
		t.Fatalf("failed bundle changed existing archive: before=%d bytes after=%d bytes; error=%v", len(before), len(after), err)
	}
}

