cat > cmd/entire/cli/mcp_cancel_test.go <<'EOF'
package cli

import (
 "bytes"
 "context"
 "errors"
 "io"
 "os"
 "strings"
 "sync"
 "testing"
 "time"
)

type mcpObservedInput struct {
 io.ReadCloser
 entered chan struct{}
 once sync.Once
 closes int
}

func (r *mcpObservedInput) Read(p []byte) (int, error) {
 r.once.Do(func() { close(r.entered) })
 return r.ReadCloser.Read(p)
}

func (r *mcpObservedInput) Close() error {
 r.closes++
 return r.ReadCloser.Close()
}

func TestMCPServer_CancelBlockedInput(t *testing.T) {
 t.Parallel()
 for _, native := range []bool{false, true} {
  for _, partial := range []bool{false, true} {
   name := "memory"
   if native { name = "native" }
   if partial { name += "/partial" } else { name += "/idle" }
   t.Run(name, func(t *testing.T) {
    t.Parallel()
    var r io.ReadCloser
    var w io.WriteCloser
    if native {
     var err error
     r, w, err = os.Pipe()
     if err != nil { t.Fatal(err) }
    } else { r, w = io.Pipe() }
    defer r.Close()
    defer w.Close()
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()
    input := &mcpObservedInput{ReadCloser:r, entered:make(chan struct{})}
    done := make(chan error, 1)
    var out bytes.Buffer
    root := NewRootCmd()
    go func() { done <- runMCPServer(ctx, root, input, &out) }()
    select {
    case <-input.entered:
    case <-time.After(5*time.Second): t.Fatal("server did not read input")
    }
    if partial {
     if _, err := io.WriteString(w, `{"jsonrpc":"2.0","id":1`); err != nil { t.Fatal(err) }
    }
    cancel()
    select {
    case err := <-done:
     if !errors.Is(err, context.Canceled) { t.Fatalf("error = %v, want cancellation", err) }
    case <-time.After(5*time.Second):
     _ = w.Close()
     <-done
     t.Fatal("server required writer close to stop")
    }
    if input.closes != 1 { t.Errorf("input closed %d times, want 1", input.closes) }
    if out.Len() != 0 { t.Errorf("cancellation wrote a protocol response: %s", out.String()) }
   })
  }
 }
}

func TestMCPServer_AlreadyCancelled(t *testing.T) {
 t.Parallel()
 ctx, cancel := context.WithCancel(context.Background())
 cancel()
 input := &mcpObservedInput{ReadCloser:io.NopCloser(strings.NewReader(`{"jsonrpc":"2.0","id":1,"method":"ping"}`)), entered:make(chan struct{})}
 var out bytes.Buffer
 err := runMCPServer(ctx, NewRootCmd(), input, &out)
 if !errors.Is(err, context.Canceled) { t.Fatalf("error = %v, want cancellation", err) }
 select {
 case <-input.entered: t.Error("read input after cancellation")
 default:
 }
 if input.closes != 1 || out.Len() != 0 { t.Fatalf("closes = %d, output = %q", input.closes, out.String()) }
}

func TestMCPServer_ClosesInputOnReturn(t *testing.T) {
 t.Parallel()
 readErr := errors.New("input failed")
 writeErr := errors.New("output failed")
 for _, tc := range []struct {
  name string
  in io.ReadCloser
  out io.Writer
  want error
 }{
  {"EOF", io.NopCloser(strings.NewReader("")), io.Discard, nil},
  {"read error", io.NopCloser(mcpErrorReader{readErr}), io.Discard, readErr},
  {"write error", io.NopCloser(strings.NewReader("{invalid}\n")), mcpErrorWriter{writeErr}, writeErr},
  {"oversize", io.NopCloser(strings.NewReader(strings.Repeat("x", maxMCPMessageBytes+1))), io.Discard, nil},
 } {
  t.Run(tc.name, func(t *testing.T) {
   t.Parallel()
   ctx, cancel := context.WithCancel(context.Background())
   defer cancel()
   input := &mcpObservedInput{ReadCloser:tc.in, entered:make(chan struct{})}
   err := runMCPServer(ctx, NewRootCmd(), input, tc.out)
   if !errors.Is(err, tc.want) { t.Fatalf("error = %v, want %v", err, tc.want) }
   cancel()
   if input.closes != 1 { t.Fatalf("closes = %d, want 1", input.closes) }
  })
 }
}

type mcpErrorReader struct { err error }
func (r mcpErrorReader) Read([]byte) (int,error) { return 0,r.err }
type mcpErrorWriter struct { err error }
func (w mcpErrorWriter) Write([]byte) (int,error) { return 0,w.err }
EOF
mise run fmt
mise exec -- go test -race ./cmd/entire/cli -run '^TestMCPServer_' -count=1 -timeout=90s

