type mcpObservedInput struct {
	io.ReadCloser

	entered chan struct{}
	once    sync.Once
	closes  int
}

func (r *mcpObservedInput) Read(p []byte) (int, error) {
	r.once.Do(func() { close(r.entered) })
	return r.ReadCloser.Read(p)
}

func (r *mcpObservedInput) Close() error {
	r.closes++
	return r.ReadCloser.Close()
}

